// 量级示例数据（用于理解各段相对占比，非实测）
const PHASES = [
  ['Queueing/Stalled', 4, '同源并发已满或等待可用连接'],
  ['DNS Lookup', 0, '命中缓存（首次约 20–120ms）'],
  ['Initial Connection', 15, 'TCP 三次握手，约 1 RTT'],
  ['SSL/TLS', 30, 'TLS 1.3 约 1 RTT（会话恢复可 0-RTT）'],
  ['Request Sent', 1, '请求报文上行（很小）'],
  ['Waiting (TTFB)', 180, '服务端处理 —— 变量最大，优化重点'],
  ['Content Download', 45, '响应体下行，取决于体积与带宽'],
];

const total = PHASES.reduce((s, p) => s + p[1], 0);

console.log('阶段                耗时      占比');
console.log('-------------------  -------  -------');
for (const [name, ms, note] of PHASES) {
  const pct = ((ms / total) * 100).toFixed(1) + '%';
  console.log(name.padEnd(20) + ms.toString().padStart(4) + ' ms  ' + pct.padStart(7) + '   ' + note);
}
console.log('-------------------  -------');
console.log('合计'.padEnd(20) + total.toString().padStart(4) + ' ms');
console.log('');
console.log('定位口诀（对应浏览器开发者工具 Network → Timing）：');
console.log('  TTFB 高            → 后端慢（查 SQL、下游依赖、锁）');
console.log('  Content Download 高 → 体积大（查压缩 gzip/br、图片尺寸）');
console.log('  Stalled/Queueing 高 → 并发受限（同源连接数、Keep-Alive 复用）');
console.log('  DNS/TLS 高         → 用 dns-prefetch / preconnect / HTTP2 多路复用摊薄');
